INSERT INTO public.recipes (household_id, title, meal_type, ingredients, steps, points) VALUES
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Granola d'oléagineux et lait ou yaourt végétal$t$, 'petit_dej', $j$[{"name":"Amandes blanches ou effilées","quantity":""},{"name":"Noix de coco râpée","quantity":""},{"name":"Chips de coco","quantity":""},{"name":"Noix de Grenoble, macadamia, pécan","quantity":""},{"name":"Noisettes","quantity":""},{"name":"Pignons de pin","quantity":""},{"name":"Pistaches","quantity":""},{"name":"Noix du Brésil (concassées)","quantity":"1 poignée"},{"name":"Graines de lin (crues)","quantity":""},{"name":"Graines de sésame","quantity":""},{"name":"Cannelle / vanille / cardamome / curcuma / mélange 4 épices","quantity":""},{"name":"Chocolat 80% min râpé / Cacao","quantity":""},{"name":"Huile de coco","quantity":""},{"name":"Beurre de noisettes","quantity":""}]$j$::jsonb, $j$["Option 1 - Cru : Mélangez les ingrédients choisis, avec un peu d'huile de coco et de beurre de noisettes.","Option 2 - Cuit à la poêle (ou wok) : Sur feu moyen, faites chauffer 1 à 2 càs d'huile de coco + 1 à 2 càs de beurre de noisettes dans un wok ou une grande poêle, jusqu'à obtenir un mélange homogène. Ajoutez-y les ingrédients + 1 ou 2 cracks de sel de l'Himalaya, et faites-les dorer.","Attention à ne surtout pas carboniser, il vaut mieux cuire lentement et à basse température.","Ne pas cuire les graines de lin ! Ajoutez-les crues au moment de manger.","Option 3 - Cuit au four (plus long) : Faites fondre 2 càs d'huile de coco + beurre de noisette.","Mélangez les ingrédients + le crack de sel dans un récipient (sauf graines de lin), avec l'huile de coco et le beurre de noisettes fondus.","Étalez le mélange sur une plaque.","Cuisez au four assez longtemps (selon votre goût) à une 100e de °C."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Pain express$t$, 'dejeuner', $j$[{"name":"Oeufs","quantity":"6"},{"name":"Farine de coco","quantity":"50g"},{"name":"Farine d'amandes","quantity":"50g"},{"name":"Psyllium","quantity":"2 càs"},{"name":"Huile d'olive","quantity":"1 càs"},{"name":"Vinaigre de cidre","quantity":"1 càs"},{"name":"Bicarbonate de soude alimentaire","quantity":"1/4 càc"},{"name":"Sel","quantity":""},{"name":"Huile de coco (optionnel)","quantity":""}]$j$::jsonb, $j$["Mélangez les éléments secs. Dans un second plat, mélangez les jaunes d'oeufs avec l'huile d'olive et le vinaigre.","Dans un 3e plat, battez les blancs d'oeufs en neige.","Incorporez délicatement les blancs d'oeufs au mélange humide de l'étape 2 avec une spatule, en effectuant des mouvements circulaires, pour ne pas casser ceux-ci.","Ajoutez progressivement le mélange sec au mélange humide, mélangez délicatement pour obtenir une pâte homogène.","Graissez un moule à cake avec un peu d'huile de coco, ou d'olive et mettez-y la pâte.","Cuisez au four à 165°C pendant environ une heure 15. Le dessus doit être doré, et l'intérieur du pain, peu humide.","Laissez refroidir. Se conserve 3 à 4 jours au sec."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Volaille à la sauce champignons$t$, 'diner', $j$[{"name":"Filet de dinde ou de poulet","quantity":""},{"name":"Champignons au choix","quantity":""},{"name":"Gousses d'ail","quantity":"2"},{"name":"Oignon","quantity":"1"},{"name":"Brique de crème d'amande ou coco","quantity":"1"},{"name":"Parmesan râpé","quantity":""},{"name":"Sel, poivre","quantity":""},{"name":"Huile d'olive","quantity":""}]$j$::jsonb, $j$["Faites revenir l'ail pressé dans de l'huile d'olive à feu moyen (l'huile ne doit pas fumer). Ajoutez l'oignon émincé et laissez cuire à feu doux.","Ajoutez ensuite les champignons préalablement lavés et découpés, ajoutez la crème d'amande, le parmesan râpé, le sel et le poivre. Laissez cuire à petit feu jusqu'à ce que les champignons soient ramolis et que la sauce soit homogène.","Pendant ce temps, cuisez votre viande.","Servez et dégustez avec les légumes de votre choix."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Pancakes amande et coco$t$, 'dejeuner', $j$[{"name":"Oeufs","quantity":"2"},{"name":"Poudre d'amandes","quantity":"60g"},{"name":"Farine de coco","quantity":"20g"},{"name":"Lait d'amande ou de coco","quantity":"3 càs"},{"name":"Huile de coco","quantity":""},{"name":"Sel de l'Himalaya","quantity":""},{"name":"Vanille (option)","quantity":""}]$j$::jsonb, $j$["Dans un plat, battez les oeufs et le lait végétal, avec un crack de sel et éventuellement de la vanille.","Ajoutez la poudre d'amandes, mélangez bien, ajoutez ensuite la farine de coco, et mélangez pour obtenir une pâte homogène.","Faites chauffer une poêle avec un peu d'huile de coco.","Placez environ la moitié de la pâte dans la poêle, écrasez-la légèrement et modelez-la pour obtenir la forme du pancake.","Cuisez à feu moyen avec un couvercle. Retournez quand c'est doré, et faites de même pour l'autre côté.","Servez et dégustez chaud ou froid."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Purée de céleri-rave gratinée$t$, 'diner', $j$[{"name":"Céleri-rave","quantity":"1"},{"name":"Lait d'amande","quantity":"5dl"},{"name":"Eau","quantity":"5dl"},{"name":"Beurre","quantity":"150g"},{"name":"Oeuf","quantity":"1"},{"name":"Poudre d'amande","quantity":""},{"name":"Parmesan râpé","quantity":""},{"name":"Ail en poudre","quantity":""},{"name":"Sel, poivre","quantity":""}]$j$::jsonb, $j$["Coupez le céleri-rave en dés et faites-le cuire dans le lait d'amande et l'eau. Quand il est ramolli, égouttez pour ne garder que peu de liquide dans la casserole.","Tant que c'est chaud, ajoutez le beurre, du sel et du poivre (éventuellement de la noix de muscade), et mixez le tout pour obtenir une purée bien lisse.","Placez la purée dans un plat pour aller au four.","Battez un oeuf, et dans un autre bol, mélangez de la poudre d'amande avec du parmesan râpé un peu de poudre d'ail et un crack ou deux de sel.","Avec un pinceau, étalez l'oeuf battu sur la purée. Saupoudrez ensuite une bonne couche du mélange amande/parmesan/ail.","Cuisez au four à 200°C sur grill pendant 15-20 minutes pour que le dessus soit bien doré."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Muesli pré-workout anti-inflammatoire$t$, 'petit_dej', $j$[{"name":"Flocons de sarrasin ou de riz","quantity":"500g"},{"name":"Raisins secs","quantity":""},{"name":"Noix de coco râpée","quantity":""},{"name":"Copeaux de coco","quantity":""},{"name":"Noisettes blanches","quantity":""},{"name":"Baies de goji","quantity":""},{"name":"Chocolat","quantity":""},{"name":"Dattes","quantity":""},{"name":"Abricots secs","quantity":""},{"name":"Pomme séchée","quantity":""},{"name":"Mangue séchée","quantity":""},{"name":"Cannelle","quantity":""},{"name":"Mélange 4 épices","quantity":""},{"name":"Vanille","quantity":""},{"name":"Cacao","quantity":""}]$j$::jsonb, $j$["Videz les flocons de sarrasin ou de riz dans un grand plat cul de poule.","Coupez ce qui doit l'être en petits morceaux (dattes, abricots, pomme, mangue, chocolat...).","Ajoutez tous vos ingrédients et mélangez bien. Dosez en fonction de votre goût (plus ou moins sucré).","Ajoutez une bonne pincée de mélange 4 épices, cannelle, cacao, vanille, ou même curcuma.","Mélangez bien et stockez au sec dans un bocal en verre."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Quiche sans pâte$t$, 'diner', $j$[{"name":"Oeufs","quantity":"6"},{"name":"Lardons","quantity":"+/- 200g"},{"name":"Gousses d'ail","quantity":"1 à 2"},{"name":"Crème d'amande","quantity":"200ml"},{"name":"Carotte","quantity":"1"},{"name":"Brocoli","quantity":"1 poignée"},{"name":"Chou frisé","quantity":"1 poignée"},{"name":"Parmesan râpé","quantity":"un peu"},{"name":"Fromage râpé (optionnel)","quantity":"une poignée"},{"name":"Sel, poivre","quantity":""}]$j$::jsonb, $j$["Cuisez les lardons afin qu'ils soient bien dorés, puis laissez refroidir.","Battez les oeufs, ajoutez l'ail pressé, la crème, le sel et le poivre et mélangez bien.","Coupez la carotte très finement, ainsi que les fleurettes de brocoli, et ciselez le chou frisé.","Ajoutez les lardons et le reste des légumes dans les oeufs, le fromage, mélangez le tout.","Huilez un moule à tarte, et répartissez-y la préparation. Enfournez pour 1h - 1h15 à 170 degrés sur chaleur tournante.","Sortez la quiche quand elle est bien dorée."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Rillettes de maquereaux sur lit d'aubergine$t$, 'diner', $j$[{"name":"Aubergine","quantity":"1"},{"name":"Petite échalote","quantity":"1"},{"name":"Maquereaux en boîte à l'huile d'olive","quantity":""},{"name":"Câpres","quantity":"2 càc"},{"name":"Féta (optionnel) ou mayonnaise à l'huile de colza","quantity":"50g ou 2 càs"},{"name":"Ciboulette","quantity":""},{"name":"Persil","quantity":""},{"name":"Noisettes sans peau ou amandes blanches","quantity":""},{"name":"Salade","quantity":""}]$j$::jsonb, $j$["La veille ou plus tôt dans la journée, coupez l'aubergine en tranches de 1 cm environ, et cuisez-la au four avec un filet d'huile d'olive, 45 minutes à 165°C.","Hachez finement l'échalote, émiettez les maquereaux avec une fourchette, écrasez la féta.","Mélangez les maquereaux, l'échalote, les câpres, le persil, la ciboulette, et ajoutez un peu de l'huile d'olive de la boîte de poisson pour que ce soit moins sec.","Concassez quelques noisettes.","Dressez les tranches d'aubergine, mettez un peu de salade de saison par dessus, ensuite 2 bonnes cuillères à soupe de préparation, et terminez par les noisettes concassées et un crack de poivre."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Rochers coco-amande$t$, 'collation', $j$[{"name":"Blanc d'oeuf","quantity":"1"},{"name":"Noix de coco râpée","quantity":""},{"name":"Amande en poudre","quantity":""},{"name":"Copeaux de coco, chocolat très noir, cacao nibs, amandes effilées (pour la déco)","quantity":""}]$j$::jsonb, $j$["Montez le blanc en neige, avec une spatule, incorporez la noix de coco et la poudre d'amande : quantités et proportions selon votre goût. Plus vous en mettrez, plus les rochers seront secs.","Réalisez des petites quenelles à l'aide de 2 cuillères à soupe, et répartissez-les sur une plaque couverte de papier cuisson.","Cuisez au four 25 minutes à 150 degrés. Vous pouvez diminuer le temps de cuisson pour que ce soit moins sec."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Petits pains ronds$t$, 'dejeuner', $j$[{"name":"Farine d'amande","quantity":"100g"},{"name":"Farine de coco","quantity":"30g"},{"name":"Graines de chia","quantity":"10g"},{"name":"Psyllium","quantity":"80g"},{"name":"Bicarbonate de soude alimentaire","quantity":"1/2 càc"},{"name":"Eau bouillante","quantity":"360 ml"},{"name":"Vinaigre de cidre","quantity":"1 càs"},{"name":"Huile d'olive","quantity":"1 càs"},{"name":"Cracks de sel","quantity":"quelques"}]$j$::jsonb, $j$["Mélangez la poudre d'amande, la farine de coco, le psyllium, les graines de chia, le bicarbonate alimentaire et le sel.","Faites bouillir 360 ml d'eau, ajoutez-la au mélange sec, et mélangez le tout à l'aide d'une spatule.","Ajoutez le vinaigre et l'huile d'olive, mélangez avec une spatule ou à la main, pour obtenir une boule homogène.","Placez-la dans un linge propre humide, et laissez reposer 10 min.","Préparez une plaque pour le four avec papier sulfurisé.","Séparez la pâte en 5-6 morceaux, et faire des boules. Mouillez-vous légèrement les mains pour la confection de chaque petit pain, afin d'homogénéiser la pâte.","Cuisez 1h20 au four à 160°C, sortez, et laissez refroidir."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Le pain-cake$t$, 'dejeuner', $j$[{"name":"Poudre d'amande","quantity":"200g"},{"name":"Psyllium (blond)","quantity":"100g"},{"name":"Jaunes d'œufs","quantity":"4"},{"name":"Poudre à lever","quantity":"1 sachet"},{"name":"Vinaigre de cidre","quantity":"1 càc"},{"name":"Huile d'olive","quantity":"5 càs"},{"name":"Lait d'amande","quantity":"1 trait"},{"name":"Eau","quantity":"un peu"},{"name":"Cracks de sel de l'Himalaya","quantity":"quelques"},{"name":"Graines de sésame","quantity":""}]$j$::jsonb, $j$["Mélangez les éléments secs et mélangez à part les éléments mouillés, sauf l'eau.","Ajoutez le mélange mouillé au mélange sec, ensuite un peu d'eau pour que la pâte se tienne et ne soit pas trop friable.","Faites une boule et saupoudrez-la de graines de sésame.","Cuisez au four 1h30 à 160 degrés et encore 15' sur grill si vous le trouvez un peu pâle."]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Cake salé courgette et féta$t$, 'diner', $j$[{"name":"Oeufs","quantity":"4"},{"name":"Courgette","quantity":"1"},{"name":"Féta","quantity":"100g"},{"name":"Gousses d'ail","quantity":"1 à 2"},{"name":"Tomates cerises","quantity":""},{"name":"Herbes fraîches","quantity":""},{"name":"Sel, poivre","quantity":""},{"name":"Epices au choix","quantity":""},{"name":"Lardons ou jambon de qualité","quantity":""}]$j$::jsonb, $j$["Hachez une ou deux gousses d'ail selon votre goût, ajoutez 4 œufs et un peu de féta en morceaux. Mixez le tout.","Râpez une courgette préalablement épluchée, coupez les tomates cerise en 4 et ajoutez le tout à la préparation. Ajoutez du jambon de qualité coupé en morceaux ou des lardons préalablement cuits.","Ajoutez enfin sel, poivre, romarin (et épices de votre choix), quelques morceaux de féta entiers, râpez un peu de parmesan si vous en avez...","Hop, au four dans un moule à cake huilé, pendant 1h à 160 degrés, ensuite 20 min sur chaleur tournante + grill."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Crackers amande sucrés ou salés$t$, 'collation', $j$[{"name":"Poudre d'amande","quantity":"100g"},{"name":"Farine de coco","quantity":"30g"},{"name":"Beurre","quantity":"50g"},{"name":"Oeuf","quantity":"1"},{"name":"Jaune d'oeuf","quantity":"1"},{"name":"Crack de sel","quantity":"1"}]$j$::jsonb, $j$["Faites ramollir le beurre.","Mélangez la poudre d'amande, la farine de coco et le sel.","Ajoutez l'oeuf + le jaune d'oeuf + le beurre préalablement mélangés.","Mélangez le tout pour que la pâte soit homogène, elle doit former une boule qui se tient bien et ne se désagrège pas.","Préchauffez le four à 180°C. Sur une plaque de cuisson, placez un papier sulfurisé et étalez votre pâte assez finement à l'aide d'un rouleau à pâtisserie.","Enfournez pour 30 - 40 minutes, voyez si la cuisson vous convient."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Café bonheur$t$, 'petit_dej', $j$[{"name":"Café chaud","quantity":"1/2 tasse"},{"name":"Lait de coco chaud","quantity":"1/2 tasse"},{"name":"Beurre bio","quantity":"1 càs"},{"name":"Huile de coco ou huile MTC","quantity":"1 càs"},{"name":"Poudre de cacao 100%","quantity":"1 càs"},{"name":"Vanille en poudre","quantity":""}]$j$::jsonb, $j$["Faites couler votre café (ou déca) comme d'habitude.","Faites chauffer 1/2 tasse de lait de coco dans un poêlon.","Mixez ensemble l'équivalent d'1/2 tasse de café, le lait chaud, le beurre, l'huile et le cacao en poudre, jusqu'à ce que le mélange soit bien lisse et forme une belle mousse.","Servez, saupoudrez de vanille pure et dégustez."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Banana bread pré-workout$t$, 'collation', $j$[{"name":"Oeufs","quantity":"2"},{"name":"Bananes","quantity":"3"},{"name":"Farine (sarrasin, riz blanc, châtaignes, patates douces...)","quantity":"200g"},{"name":"Beurre bio","quantity":"50g"},{"name":"Lait d'amande ou de coco","quantity":"100ml"},{"name":"Bicarbonate de soude alimentaire","quantity":"1 càc"},{"name":"Vinaigre de cidre","quantity":"1 càs"},{"name":"Vanille","quantity":""},{"name":"Sel de l'Himalaya","quantity":"1 crack"},{"name":"Cannelle","quantity":""}]$j$::jsonb, $j$["Faites fondre doucement le beurre.","Pendant ce temps, dans un plat, battez les oeufs, le lait végétal, le vinaigre de cidre, le sel, le bicarbonate de soude et la vanille. Ajoutez le beurre fondu et mélangez bien.","Écrasez 2 bananes bien mûres, ajoutez-les au mélange et battez le tout, pour que ce soit homogène.","Ajoutez progressivement la farine, continuez à bien mélanger.","Si vous voulez mettre un autre fruit dans le cake, préparez-le. Par exemple, coupez une pomme en lamelles.","Huilez un moule à cake, versez-y la pâte. Placez vos lamelles de pomme dans la pâte et par dessus, ou décorez avec une banane coupée en 2.","Saupoudrez le tout de cannelle ou de mélange 4 épices.","Cuisez 1h au four à 165°C."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Butternut farci à la viande hachée$t$, 'diner', $j$[{"name":"Butternut","quantity":"1"},{"name":"Viande hachée au choix","quantity":"env. 500g"},{"name":"Oeuf","quantity":"1"},{"name":"Gousses d'ail","quantity":"2"},{"name":"Oignon ou échalotes","quantity":"1 oignon ou 2 échalotes"},{"name":"Huile d'olive","quantity":""},{"name":"Sel, poivre, herbes de provence, romarin, thym, origan","quantity":""},{"name":"Parmesan (optionnel)","quantity":""}]$j$::jsonb, $j$["Pelez le butternut, enlevez la partie centrale avec les graines.","Creusez-le avec une cuillère à soupe et récupérez la chair dans un plat arrondi.","Ajoutez dans ce plat : la viande hachée, les gousses d'ail pressées, l'oignon émincé, l'oeuf, les épices et mélangez bien le tout pour que la farce soit homogène.","Placez vos moitiés de butternut sur une plaque de cuisson ou dans un plat, versez un filet d'huile d'olive, un crack de sel et un crack de poivre.","Remplissez avec la farce et ajoutez du parmesan râpé ou en fines tranches, par dessus.","Placez au four à 165 degrés sur chaleur tournante pendant 1h environ (la farce doit être cuite et le butternut ramolli)."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Golden latté$t$, 'petit_dej', $j$[{"name":"Lait de coco","quantity":"1 tasse"},{"name":"Curcuma en poudre","quantity":"1 càc bombée"},{"name":"Gingembre en poudre","quantity":"1/3 de càc"},{"name":"Beurre bio","quantity":"1 càs"},{"name":"Huile de coco ou huile MCT","quantity":"1 càs"},{"name":"Poivre noir","quantity":"1 pincée"},{"name":"Cannelle","quantity":"1 pincée"}]$j$::jsonb, $j$["Versez l'équivalent d'une tasse de lait de coco dans un poêlon, faites chauffer à feu doux.","Ajoutez le curcuma, le gingembre, le poivre noir, mélangez.","Ajoutez ensuite le beurre et l'huile et fouettez bien pour que le mélange soit homogène et légèrement mousseux.","Quand c'est bien chaud, servez dans une tasse, ajoutez une pincée de cannelle et dégustez."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Cookies crapuleux$t$, 'collation', $j$[{"name":"Farine d'amande ou coco","quantity":"200g"},{"name":"Psyllium (amande ou coco)","quantity":"100g"},{"name":"Oeufs","quantity":"2"},{"name":"Sel","quantity":"1 pincée"},{"name":"Poudre à lever ou bicarbonate de soude alimentaire","quantity":"1 sachet"},{"name":"Huile de coco fondue","quantity":"3 càs"},{"name":"Vinaigre de cidre","quantity":"1 càs"},{"name":"Beurre d'amande ou de noisettes, ou les deux","quantity":"2 càs"},{"name":"Lait d'amande ou de coco (si la pâte est trop sèche)","quantity":"1 trait"}]$j$::jsonb, $j$["Mélangez tout ce qui est liquide : les oeufs, ajoutez l'huile de coco, le vinaigre, et la pâte d'oléagineux, battez bien le tout.","Mélangez tout ce qui est solide, et ajoutez-y la phase liquide. Mélangez avec une spatule.","Préparez une feuille de papier sulfurisé sur une plaque de cuisson, faites des petites boules de pâte avec les mains et écrasez-les pour former vos cookies, saupoudrez de garniture au choix et enfournez +/- 30 minutes à 170°C."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Matcha latté épicé$t$, 'petit_dej', $j$[{"name":"Lait de coco","quantity":"1 tasse"},{"name":"Thé matcha ou thé à infuser","quantity":"1 càc"},{"name":"Beurre bio","quantity":"1 càs"},{"name":"Huile de coco ou huile MCT","quantity":"1 càs"},{"name":"Mélange 4 épices ou vanille en poudre","quantity":""}]$j$::jsonb, $j$["Versez l'équivalent d'une tasse de lait de coco dans un poêlon, faites chauffer à feu doux. Si vous avez de la poudre de thé matcha, versez-en une cuillère à café dans le lait de coco.","Fouettez bien, ajoutez le beurre et l'huile de coco, et continuez à fouetter pour obtenir une belle mousse. Quand la boisson est assez chaude, que le beurre et l'huile ont fondu et que c'est bien homogène, servez.","Ajoutez une bonne pincée de mélange 4 épices ou de vanille si vous préférez une saveur plus douce, et dégustez bien chaud.","Si vous n'avez pas de poudre de thé matcha, laissez bien infuser votre sachet de thé dans le lait de coco, pendant la cuisson, ensuite enlevez-le, et faites exactement comme mentionné plus haut, en fouettant bien également."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Mousse de macadamia et amandes$t$, 'dejeuner', $j$[{"name":"Noix de macadamia","quantity":"1 poignée"},{"name":"Amandes blanches","quantity":"1 poignée"},{"name":"Jus de citron","quantity":"1/2"},{"name":"Lait d'amande","quantity":"1 trait"},{"name":"Sel de l'Himalaya","quantity":""},{"name":"Levure noble","quantity":"2 pincées"}]$j$::jsonb, $j$["Placez les amandes et les noix de macadamia dans un bocal avec de l'eau et, si vous le voulez, un peu de levure noble.","Refermez et laissez macérer toute la nuit à température ambiante.","Le lendemain, enlevez l'excédant d'eau, versez le tout dans un hachoir ou un blinder, ajoutez le jus d'1/2 citron, quelques cracks de sel, un trait de lait d'amande et mixez jusqu'à obtenir une sorte de mousse. Ajustez la texture grâce au lait d'amande, assaisonnez avec le citron et le sel selon votre goût. Vous pouvez agrémenter avec des fines herbes, des épices, du poivre...","À tartiner sur crackers de graines, pain-cake, ou même gratiné au four sur vos légumes préférés !"]$j$::jsonb, 10),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Tartinade noix de coco et vanille$t$, 'petit_dej', $j$[{"name":"Noix de coco râpée","quantity":"100g"},{"name":"Amandes blanches","quantity":"100g"},{"name":"Huile de coco","quantity":"2 càs"},{"name":"Vanille","quantity":""},{"name":"Sel","quantity":"1 crack"}]$j$::jsonb, $j$["Mettez la noix de coco râpée, les amandes blanches et l'huile de coco dans un hachoir ou un blinder.","Mixez assez longtemps jusqu'à ce que le mélange forme une pâte. Ajoutez avec de l'huile de coco si la pâte est trop sèche. Mixez bien pour que la préparation soit uniforme.","Ajoutez la vanille et le crack de sel et re mixez encore un instant."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Poivron jaune au thon$t$, 'diner', $j$[{"name":"Poivron jaune","quantity":"1"},{"name":"Thon égoutté","quantity":"80g"},{"name":"Jus de citron","quantity":"1 càs"},{"name":"Mayonnaise à l'huile de colza","quantity":"1 càs"},{"name":"Huile d'olive","quantity":"1 càs"},{"name":"Oeuf dur","quantity":"1"},{"name":"Persil","quantity":""},{"name":"Sel, poivre","quantity":""}]$j$::jsonb, $j$["La veille, cuisez le poivron jaune au four, coupé en deux, avec un filet d'huile d'olive, 45 minutes à 165°C. Conservez au frigo.","Écrasez le thon avec l'oeuf dur, ajoutez le reste des ingrédients pour former un mélange homogène.","Assaisonnez à votre goût.","Placez 1/2 poivron dans une assiette, remplissez-le avec la préparation au thon, ajoutez un brin de persil pour la présentation, et dégustez avec une petite salade."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Wrap d'oeuf au saumon mi-cuit$t$, 'diner', $j$[{"name":"Blancs d'oeufs","quantity":"1 ou 2"},{"name":"Oeuf","quantity":"1"},{"name":"Pavé de saumon (sauvage si possible)","quantity":"1/2"},{"name":"Légumes au choix pour la garniture","quantity":""},{"name":"Huile d'olive","quantity":"1 filet"},{"name":"Sauce soja","quantity":"1 filet"},{"name":"Graines de sésame (optionnel)","quantity":""},{"name":"Sel, poivre, romarin","quantity":""}]$j$::jsonb, $j$["Battez les 2 blancs et l'oeuf entier dans un bol avec sel, poivre et romarin. Éventuellement un peu de lait végétal.","Répartissez dans une crêpière bien huilée et faites cuire à petit feu. Quand la crêpe est assez cuite, retournez-la.","Dans le même temps, faites cuire votre pavé de saumon à petit feu, salez, poivrez, ajoutez un petit filet de sauce soja. Vous pouvez faire dorer un peu les côtés, mais l'intérêt est de ne pas le cuire trop fort pour garder des oméga 3 de bonne qualité. D'où l'intérêt qu'il reste un peu cru à l'intérieur.","Mettez votre wrap dans l'assiette et garnissez comme vous voulez, saupoudrez de graines de sésame, et dégustez !"]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Saumon mariné cru ou cuit$t$, 'diner', $j$[{"name":"Filet de saumon (sauvage)","quantity":"1"},{"name":"Huile d'olive","quantity":""},{"name":"Jus de citrons","quantity":"2"},{"name":"Gousse d'ail (frais)","quantity":"1"},{"name":"Gingembre râpé","quantity":"1 à 2 cm"},{"name":"Herbes fraîches","quantity":""},{"name":"Sauce soja","quantity":""},{"name":"Sel, poivre","quantity":""},{"name":"Curcuma, paprika","quantity":""}]$j$::jsonb, $j$["Le matin ou la veille, préparez la marinade dans un plat en verre : mélangez un bon trait d'huile d'olive avec les jus de citrons, la sauce soja, l'ail pressé, le gingembre râpé, les herbes fraîches (ciboulette, persil, aneth, romarin...), les épices que vous aimez (paprika, curcuma).","Mélangez bien, goûtez et ajustez les goûts si nécessaire. Ensuite ajoutez le saumon, coupé en gros morceaux, ou déjà en carpaccio si vous voulez qu'il soit plus cuit par votre marinade. Couvrez et laissez macérer au frigo pendant plusieurs heures. Vous pouvez de temps à autre mélanger ou mouiller votre saumon avec la marinade si vous en avez l'occasion.","Deux options de dégustation : si vous aimez le poisson cru, dégustez votre saumon tel quel, saucé avec la marinade, avec un accompagnement au choix. Il sera légèrement cuit par le jus de citron. Si vous préférez le saumon cuit, mettez-le dans une poêle et faites-le cuire à basse température, jusqu'à ce qu'il soit à votre goût.","Servez la marinade comme condiment, après la cuisson."]$j$::jsonb, 15),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Crêpes à la farine de riz et de sarrasin$t$, 'petit_dej', $j$[{"name":"Oeuf","quantity":"1"},{"name":"Farine de riz blanc","quantity":"150g"},{"name":"Farine de sarrasin (ou de riz blanc)","quantity":"50g"},{"name":"Lait de coco ou d'amandes (ou 100 ml de lait de coco + eau)","quantity":"300 ml environ"},{"name":"Banane mûre","quantity":"1/2"},{"name":"Vanille en poudre, cannelle (optionnel)","quantity":""}]$j$::jsonb, $j$["Pesez la farine dans un plat avec un fond arrondi, mélangez les deux farines.","Écrasez la demi banane mûre à part.","Ajoutez l'oeuf et le lait dans le bol avec la farine, mélangez, ensuite ajoutez la banane écrasée. Mélangez encore, tout en ajustant l'ajout de lait végétal (ou d'eau), pour obtenir la consistance souhaitée d'une pâte à crêpes.","Mélangez bien au fouet pour ne pas avoir de grumeaux.","Cuisez dans une poêle avec un peu de beurre bio, d'huile de coco (ou de l'huile d'olive), sans faire brûler."]$j$::jsonb, 5),
  ('d650ff09-5b09-4a57-a6b8-d725a27ce11f', $t$Fat balls à la noix de coco et aux pistaches$t$, 'collation', $j$[{"name":"Noix de coco râpée","quantity":"env. 8 càs"},{"name":"Amandes blanches","quantity":"100g"},{"name":"Huile de coco","quantity":"2 càs"},{"name":"Lait de coco","quantity":"un trait"},{"name":"Pistaches","quantity":"env. 60g"},{"name":"Sel de l'Himalaya","quantity":""},{"name":"Vanille (optionnel)","quantity":""}]$j$::jsonb, $j$["Mettez les amandes blanches et l'huile de coco fondue dans un mixer. Mixez le tout pour obtenir une pâte.","Ajoutez petit à petit des cuillères à soupe de coco râpée, et du lait de coco (le premier, le plus gras), que vous avez réalisé. Mixez entre les coups, pour obtenir une pâte homogène et légèrement collante.","Réservez-la dans un récipient cul de poule.","Mettez les pistaches décortiquées dans le mixer et hachez grossièrement.","Mélangez votre pâte avec les pistaches, un crack de sel et un peu de vanille, pour que le mélange soit homogène.","Formez des boules que vous roulez dans de la noix de coco râpée, placez le tout au frigo pendant min. 1h, et conservez au frigo."]$j$::jsonb, 5);
